#!/usr/bin/env python3
"""Emit repetitive register checks from the reviewed interface profile.

Arithmetic and memory execution are NOT generated from compiler plans.
Run --check in CI to detect stale generated RTL.
"""
from pathlib import Path
import argparse
import sys
ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from model.profile import REGISTERS, INITIALIZATION_REGISTERS, OPS

head = '''// SPDX-License-Identifier: MIT
`timescale 1ns/1ps
// Generated by tools/gen_regfile.py; edit the profile or generator, not this file.
// Single, fully specified task at a time. PC_DMA is used only by rk_ew_dma.
module rk_ew_regs #(
    parameter bit PC_DMA = 0
) (
    input logic clk, rst_n,
    input logic cmd_valid,
    output logic cmd_ready,
    input logic [63:0] cmd_data,
    input logic engine_busy,
    input logic engine_error,
    output logic cfg_valid,
    input logic cfg_ready,
    output logic [1:0] cfg_op,
    output logic [16:0] cfg_count,
    output logic [31:0] cfg_a, cfg_b, cfg_dst,
    output logic [31:0] cfg_next_address, cfg_next_amount,
    output logic error,
    output logic [7:0] error_code
);
    logic [20:0] seen;
    logic [12:0] init_seen;
    logic [12:0] width, rdma_width, wdma_width;
    logic [32:0] byte_count, end_a, end_b, end_dst;
    logic bad_addr;
    wire [31:0] value = cmd_data[47:16];
    wire [31:0] key = {cmd_data[63:48], cmd_data[15:0]};
    assign cfg_count = ({4'b0, width} + 17'd1) << 3;
    assign byte_count = {16'b0, cfg_count} << 1;
    assign end_a = {1'b0, cfg_a} + byte_count;
    assign end_b = {1'b0, cfg_b} + byte_count;
    assign end_dst = {1'b0, cfg_dst} + byte_count;
    assign bad_addr = (|cfg_a[3:0]) || (|cfg_b[3:0]) || (|cfg_dst[3:0]) ||
        (end_a > 33'h100000000) || (end_b > 33'h100000000) || (end_dst > 33'h100000000) ||
        ((cfg_dst != cfg_a) && ({1'b0, cfg_dst} < end_a) && ({1'b0, cfg_a} < end_dst)) ||
        ((cfg_dst != cfg_b) && ({1'b0, cfg_dst} < end_b) && ({1'b0, cfg_b} < end_dst));
    assign cmd_ready = !cfg_valid && !engine_busy && !engine_error && !error;
    always_ff @(posedge clk) begin
        if (!rst_n) begin
            seen <= 0; init_seen <= 0; width <= 0; rdma_width <= 0; wdma_width <= 0;
            cfg_a <= 0; cfg_b <= 0; cfg_dst <= 0; cfg_op <= 0;
            cfg_next_address <= 0; cfg_next_amount <= 0;
            cfg_valid <= 0; error <= 0; error_code <= 0;
        end else begin
            if (cfg_valid && cfg_ready) begin
                cfg_valid <= 0;
                seen <= 0;
                init_seen <= 0;
            end
            if (cmd_valid && cmd_ready) begin
                case (key)
'''
lines = [head]
for i, (target, addr, name, fixed) in enumerate(REGISTERS + INITIALIZATION_REGISTERS):
    lines.append(f"                    32'h{target:04x}{addr:04x}: begin // {name}\n")
    seen = f'seen[{i}]' if i < len(REGISTERS) else f'init_seen[{i-len(REGISTERS)}]'
    lines.append(f"                        {seen} <= 1'b1;\n")
    if name.startswith('next_'):
        lines.append(f'                        cfg_{name} <= value;\n')
        invalid = '(|value[3:0])' if name == 'next_address' else '(value > 65535)'
        lines.append(f"                        if ((!PC_DMA && value != 0) || (PC_DMA && {invalid})) begin error <= 1; error_code <= 8'd7; end\n")
    elif fixed is not None:
        code = 7 if name.startswith('next_') else 2
        lines.append(f"                        if (value != 32'h{fixed:08x}) begin error <= 1; error_code <= 8'd{code}; end\n")
    elif name in ('width', 'rdma_width', 'wdma_width'):
        lines.append(f"                        {name} <= value[12:0];\n")
        lines.append("                        if (value > 7999) begin error <= 1; error_code <= 8'd2; end\n")
    elif name == 'ew_config':
        lines.append('                        case (value)\n')
        for op, v in OPS.items():
            opid = {'ADD': 0, 'SUB': 1, 'MUL': 2}[op]
            lines.append(f"                            32'h{v:08x}: cfg_op <= 2'd{opid};\n")
        lines.append("                            default: begin error <= 1; error_code <= 8'd2; end\n                        endcase\n")
    else:
        out = {'src_a': 'cfg_a', 'src_b': 'cfg_b', 'dst': 'cfg_dst'}[name]
        lines.append(f'                        {out} <= value;\n')
    lines.append('                    end\n')
lines.append('''                    32'h00810008: begin
                        if (value != 32'h18) begin error <= 1; error_code <= 8'd2; end
                        else if (!(&seen) || ((|init_seen) && !(&init_seen))) begin error <= 1; error_code <= 8'd3; end
                        else if ((width != rdma_width) || ((|init_seen) && (width != wdma_width))) begin error <= 1; error_code <= 8'd6; end
                        else if (PC_DMA && cfg_next_amount != 0 && cfg_next_address == 0) begin error <= 1; error_code <= 8'd7; end
                        else if (bad_addr) begin error <= 1; error_code <= 8'd4; end
                        else cfg_valid <= 1;
                    end
                    default: begin error <= 1; error_code <= 8'd1; end
                endcase
            end
        end
    end
endmodule
''')
text = ''.join(lines)
path = ROOT / 'rtl/rk_ew_regs.sv'
p = argparse.ArgumentParser()
p.add_argument('--check', action='store_true')
args = p.parse_args()
if args.check:
    if not path.exists() or path.read_text() != text:
        sys.exit('generated RTL is stale; run python tools/gen_regfile.py')
else:
    path.write_text(text)
